752→<!-- Redirect links and searches when in dual view mode -->
753→<script>
754→document.addEventListener("DOMContentLoaded", function () {
755→  if (!window.location.pathname.startsWith("/dual")) return;
756→
757→  function getTargetPanel() {
758→    const selected = document.querySelector('input[name="targetPanel"]:checked');
759→    return selected ? selected.value : "left";
760→  }
761→
762→  function loadInPanel(panel, path) {
763→    if (!path) return;
764→    const iframe = document.getElementById(`iframe-${panel}`);
765→    if (!iframe) return;
766→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
767→    iframe.src = url;
768→    const inputBox = document.querySelector(`#panel-${panel} input`);
769→    if (inputBox) inputBox.value = path;
770→    console.log(`Loaded "${url}" into panel "${panel}"`);
771→  }
772→  
773→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
774→    link.addEventListener("click", function (e) {
775→      e.preventDefault();
776→      const path = this.getAttribute("href");
777→      loadInPanel(getTargetPanel(), path);
778→    });
779→  });
780→
781→  const idForm = document.getElementById("idsearchForm");
782→  if (idForm) {
783→    idForm.addEventListener("submit", function (e) {
784→      e.preventDefault();
785→      const input = idForm.querySelector(".idsearchTerm").value.trim();
786→      if (!input) return;
787→
788→      let path = null;
789→
790→      if (/^\d+$/.test(input)) {
791→        path = "/go_to/" + encodeURIComponent(input);
792→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
793→        const parts = input.split(/\s+/).filter(Boolean);
794→        path = "/range/" + parts.map(encodeURIComponent).join("/");
795→      } else {
796→        alert("Invalid input format.");
797→        return;
798→      }
799→
800→      loadInPanel(getTargetPanel(), path);
801→    });
802→  }
803→
804→  const searchForm = document.getElementById("searchForm");
805→  if (searchForm) {
806→    searchForm.addEventListener("submit", function (e) {
807→      e.preventDefault();
808→      const input = searchForm.querySelector(".searchTerm").value.trim();
809→      if (!input) return;
810→
811→      const path = "/search/" + encodeURIComponent(input);
812→      loadInPanel(getTargetPanel(), path);
813→    });
814→  }
815→});
816→</script>
